html:
{#- Final Account Statement (catalogue 4.7): the final contract sum built up from the
    contract, then what has been certified, retained, recovered and paid, and the
    balance; signed by both parties. -#}
{%- set award = frappe.get_doc("Awarded Quotation", doc.awarded_quotation) -%}
{%- set ipcs = frappe.get_all("Client IPC", filters={"awarded_quotation": doc.awarded_quotation, "docstatus": 1},
                              fields=["ipc_no", "period_to", "certified_amount", "retention_this_period", "advance_recovered_this_period", "net_due", "opening_invoice"],
                              order_by="ipc_no asc") -%}
{%- set variations = frappe.get_all("Variation Order", filters={"awarded_quotation": doc.awarded_quotation, "status": "Approved"},
                                    fields=["name", "subject", "total_amount"], order_by="name asc") -%}
{%- macro money(v) -%}{{ frappe.utils.fmt_money(v, currency=doc.currency) }}{%- endmacro -%}

<style>
	.fas { font-size: 9.5pt; }
	.fas h2 { margin: 0 0 2px; }
	.fas .sub { color: #666; margin-bottom: 12px; }
	.fas .meta { width: 100%; margin: 6px 0 16px; }
	.fas .meta td { padding: 2px 10px 2px 0; vertical-align: top; }
	.fas .label { color: #666; }
	.fas h4 { margin: 18px 0 6px; font-size: 10.5pt; border-bottom: 1px solid #ccc; padding-bottom: 3px; }
	.fas table.lines { width: 100%; border-collapse: collapse; }
	.fas table.lines td, .fas table.lines th { padding: 4px 6px; border-bottom: 1px solid #eee; }
	.fas table.lines th { text-align: left; font-weight: 600; background: #f3f4f2; }
	.fas table.lines th.num { text-align: right; }
	.fas .num { text-align: right; white-space: nowrap; }
	.fas .total td { font-weight: 700; border-top: 1px solid #333; border-bottom: 2px solid #333; }
	.fas .muted { color: #888; }
	.fas .sign { width: 100%; margin-top: 36px; }
	.fas .sign td { width: 50%; padding-right: 24px; vertical-align: bottom; }
	.fas .line { border-top: 1px solid #333; margin-top: 44px; padding-top: 4px; }
</style>

<div class="fas">
	<h2>{{ _("Final Account Statement") }}</h2>
	<div class="sub">{{ doc.name }} · {{ _(doc.status) }}</div>
	<table class="meta">
		<tr><td class="label">{{ _("Contract") }}</td><td><b>{{ award.title }}</b> ({{ award.name }})</td>
		    <td class="label">{{ _("Date") }}</td><td>{{ frappe.format(doc.account_date, {"fieldtype": "Date"}) }}</td></tr>
		<tr><td class="label">{{ _("Client") }}</td><td>{{ doc.customer }}</td>
		    <td class="label">{{ _("Contractor") }}</td><td>{{ doc.company }}</td></tr>
		<tr><td class="label">{{ _("Project") }}</td><td>{{ doc.project or "" }}</td>
		    <td class="label">{{ _("Practical completion") }}</td><td>{{ frappe.format(award.practical_completion_date, {"fieldtype": "Date"}) if award.practical_completion_date else "—" }}</td></tr>
	</table>

	<h4>{{ _("1. Final contract sum") }}</h4>
	<table class="lines">
		<tr><td>{{ _("Contract value as awarded") }}</td><td class="num">{{ money(doc.contract_value) }}</td></tr>
		{%- for v in variations %}
		<tr><td class="muted">&nbsp;&nbsp;{{ v.name }} {{ v.subject or "" }}</td><td class="num muted">{{ money(v.total_amount) }}</td></tr>
		{%- endfor %}
		<tr><td>{{ _("Approved variations") }}</td><td class="num">{{ money(doc.approved_variations) }}</td></tr>
		<tr><td>{{ _("Contract plus variations") }}</td><td class="num">{{ money(doc.revised_contract_value) }}</td></tr>
		{%- if doc.remeasured_value %}
		<tr><td><b>{{ _("Remeasured value of the work") }}</b> <span class="muted">({{ doc.measure_basis }})</span></td><td class="num"><b>{{ money(doc.remeasured_value) }}</b></td></tr>
		{%- endif %}
		{%- for r in doc.adjustments %}
		<tr><td>{{ r.description }}{% if not r.agreed %} <span class="muted">— {{ _("not agreed, not counted") }}</span>{% endif %}</td>
		    <td class="num{% if not r.agreed %} muted{% endif %}">{{ money(r.amount) }}</td></tr>
		{%- endfor %}
		<tr class="total"><td>{{ _("Final contract sum") }}</td><td class="num">{{ money(doc.final_contract_sum) }}</td></tr>
	</table>

	{%- if ipcs %}
	<h4>{{ _("2. Interim payment certificates") }}</h4>
	<table class="lines">
		<tr><th>{{ _("IPC") }}</th><th>{{ _("Period to") }}</th><th class="num">{{ _("Certified") }}</th><th class="num">{{ _("Retention") }}</th><th class="num">{{ _("Advance recovered") }}</th><th class="num">{{ _("Net") }}</th></tr>
		{%- for i in ipcs %}
		<tr><td>{{ i.ipc_no }}{% if i.opening_invoice %} <span class="muted">({{ _("opening") }})</span>{% endif %}</td>
		    <td>{{ frappe.format(i.period_to, {"fieldtype": "Date"}) }}</td><td class="num">{{ money(i.certified_amount) }}</td>
		    <td class="num">{{ money(i.retention_this_period) }}</td><td class="num">{{ money(i.advance_recovered_this_period) }}</td><td class="num">{{ money(i.net_due) }}</td></tr>
		{%- endfor %}
	</table>
	{%- endif %}

	<h4>{{ _("{0}. Settlement").format(3 if ipcs else 2) }}</h4>
	<table class="lines">
		<tr><td>{{ _("Final contract sum") }}</td><td class="num">{{ money(doc.final_contract_sum) }}</td></tr>
		<tr><td>{{ _("Less certified to date") }}</td><td class="num">{{ money(-doc.certified_to_date) }}</td></tr>
		<tr class="total"><td>{{ _("Balance due, before VAT") }}{% if doc.final_invoice %} <span class="muted">({{ _("final invoice") }} {{ doc.final_invoice }})</span>{% endif %}</td><td class="num">{{ money(doc.balance_due) }}</td></tr>
		<tr><td>{{ _("Advance still to recover") }}</td><td class="num">{{ money(doc.advance_balance) }}</td></tr>
		<tr><td>{{ _("Retention held") }}</td><td class="num">{{ money(doc.retention_held) }}</td></tr>
		<tr><td>{{ _("Retention released") }}</td><td class="num">{{ money(doc.retention_released) }}</td></tr>
		<tr><td>{{ _("Retention still held") }}</td><td class="num">{{ money(doc.retention_held - doc.retention_released) }}</td></tr>
		<tr><td>{{ _("Paid to date, VAT included") }}</td><td class="num">{{ money(doc.paid_to_date) }}</td></tr>
		<tr><td>{{ _("Outstanding on invoices, VAT included") }}</td><td class="num">{{ money(doc.outstanding_amount) }}</td></tr>
	</table>

	<table class="sign">
		<tr><td><div class="line">{{ _("For the contractor") }}: {{ doc.company }}</div></td>
		    <td><div class="line">{{ _("For the client") }}: {{ doc.customer }}</div></td></tr>
	</table>
</div>
